const BODY = "flowchart TD\n  A[Start] --> B[Finish]";
const flow = (config: unknown, body = BODY): string => `---\nconfig: ${JSON.stringify(config)}\n---\n${body}`;
const accepted = (source: string): boolean => validateMermaidSource(source, { allowPluginHeader: true }).ok;

const BASE_CONFIG = {
	theme: "base",
	look: "classic",
	layout: "dagre",
	themeVariables: { primaryColor: "#caeffc", lineColor: "#1a7594", fontFamily: "Menlo, Monaco, Consolas, Courier New, monospace", fontSize: "13px" }
};

describe("plugin headers: what the diagram builder writes", () => {
	test("every assembled diagram from the style recipes is accepted", () => {
		expect(ASSEMBLED.length).toBeGreaterThan(40);
		for (const [label, source] of ASSEMBLED) {
			const result = validateMermaidSource(source, { allowPluginHeader: true });
			expect({ label, ok: result.ok, reasons: result.reasons.map((reason) => reason.code) }).toEqual({ label, ok: true, reasons: [] });
		}
	});

	test("the same sources are rejected without the option, because a model never writes frontmatter", () => {
		for (const [label, source] of ASSEMBLED) {
			const result = validateMermaidSource(source);
			expect({ label, ok: result.ok, code: result.reasons[0]?.code }).toEqual({ label, ok: false, code: "frontmatter" });
		}
	});

	test("the sources use every kind of setting the builder emits", () => {
		const all = ASSEMBLED.map(([, source]) => source).join("\n");
		for (const feature of ["\"look\":\"handDrawn\"", "\"handDrawnSeed\":", "\"fontFamily\":", "\"fontSize\":", "\"xyChart\":{", "\"sankey\":{", "\"flowchart\":{\"curve\":", "\"padding\":", "\"pieOpacity\":\"1\"", "\"showValues\":true", "\"backgroundColor\":\"transparent\"", "\"pieStrokeWidth\":\"2px\"", "classDef primary"]) {
			expect({ feature, present: all.includes(feature) }).toEqual({ feature, present: true });
		}
	});

	test("a body that goes wrong after a good header is still caught", () => {
		const [, source] = ASSEMBLED[0];
		expect(accepted(`${source}\n  C[\"https://evil.example/x\"]`)).toBe(false);
		expect(accepted(`${source}\n  click A href \"https://evil.example\"`)).toBe(false);
		expect(accepted(`${source}\n  %%{init: {\"themeCSS\": \".a{}\"}}%%`)).toBe(false);
		expect(accepted(`${source}\n  A@{ img: \"https://evil.example/x.png\" }`)).toBe(false);
	});
});

describe("plugin headers: the closed schema", () => {
	test("accepts the base configuration and the single-line form with a title", () => {
		expect(accepted(flow(BASE_CONFIG))).toBe(true);
		expect(accepted(`---\ntitle: Release plan\nconfig: ${JSON.stringify(BASE_CONFIG)}\n---\n${BODY}`)).toBe(true);
		expect(accepted(`---\nconfig: ${JSON.stringify(BASE_CONFIG)}\ntitle: Release plan\n---\n${BODY}`)).toBe(true);
	});

	test("accepts the value shapes the builder uses: hex, transparent, sizes, numbers, booleans and quoted numbers", () => {
		const themeVariables = { a: "#fff", b: "#ffffff80", c: "transparent", d: "2px", e: "0px", f: "1", g: 0.5, h: 12, i: true, j: false, xyChart: { plotColorPalette: "#111111,#222222,#333333", backgroundColor: "transparent", titleColor: "#000" } };
		expect(accepted(flow({ ...BASE_CONFIG, themeVariables }))).toBe(true);
		expect(accepted(flow({ ...BASE_CONFIG, handDrawnSeed: 8, flowchart: { curve: "monotoneX", padding: 14 }, sankey: { linkColor: "gradient", nodeAlignment: "justify", showValues: true } }))).toBe(true);
	});

	test("rejects keys outside the schema, at any level", () => {
		const bad: Record<string, unknown> = {
			"themeCSS at the top": { ...BASE_CONFIG, themeCSS: ".a{color:red}" },
			"securityLevel": { ...BASE_CONFIG, securityLevel: "loose" },
			"fontFamily at the top": { ...BASE_CONFIG, fontFamily: "Menlo" },
			"startOnLoad": { ...BASE_CONFIG, startOnLoad: true },
			"a directive-like key": { ...BASE_CONFIG, init: { theme: "dark" } },
			"flowchart htmlLabels": { ...BASE_CONFIG, flowchart: { htmlLabels: true } },
			"sankey extra": { ...BASE_CONFIG, sankey: { linkColor: "gradient", prefix: "x" } },
			"empty config": {},
			"empty flowchart": { ...BASE_CONFIG, flowchart: {} }
		};
		for (const [name, config] of Object.entries(bad)) {
			expect({ name, ok: accepted(flow(config)) }).toEqual({ name, ok: false });
		}
	});

	test("rejects values outside their character sets", () => {
		const variables = (themeVariables: unknown) => ({ ...BASE_CONFIG, themeVariables });
		const bad: Record<string, unknown> = {
			"themeCSS as a variable": variables({ themeCSS: ".a{background:url(https://evil.example/x)}" }),
			"declaration injection in fontFamily": variables({ fontFamily: "x; background-image: url(https://evil.example/x)" }),
			"a quote in fontFamily": variables({ fontFamily: "Menlo\", x" }),
			"parentheses in fontFamily": variables({ fontFamily: "Menlo, url(x)" }),
			"braces in fontFamily": variables({ fontFamily: "Menlo} body{" }),
			"a backslash in fontFamily": variables({ fontFamily: "Menlo\\" }),
			"a colour name": variables({ primaryColor: "red" }),
			"a colour with a function": variables({ primaryColor: "rgb(1,2,3)" }),
			"a colour with a declaration": variables({ primaryColor: "#fff; background:url(x)" }),
			"a nested object other than xyChart": variables({ other: { a: "#fff" } }),
			"an xyChart nested deeper": variables({ xyChart: { a: { b: "#fff" } } }),
			"an xyChart value that is not a colour": variables({ xyChart: { backgroundColor: "url(x)" } }),
			"an xyChart list with a bad item": variables({ xyChart: { plotColorPalette: "#111111,red" } }),
			"an empty xyChart": variables({ xyChart: {} }),
			"a constructor key": variables({ constructor: "#fff" }),
			"a key with punctuation": variables({ "a-b": "#fff" }),
			"a huge number": variables({ a: 1e9 }),
			"an unknown theme": { ...BASE_CONFIG, theme: "evil" },
			"an unknown look": { ...BASE_CONFIG, look: "wild" },
			"the elk layout": { ...BASE_CONFIG, layout: "elk" },
			"a fractional seed": { ...BASE_CONFIG, handDrawnSeed: 1.5 },
			"a negative seed": { ...BASE_CONFIG, handDrawnSeed: -1 },
			"a string seed": { ...BASE_CONFIG, handDrawnSeed: "7" },
			"an unknown curve": { ...BASE_CONFIG, flowchart: { curve: "evil" } },
			"a negative padding": { ...BASE_CONFIG, flowchart: { padding: -1 } },
			"a sankey link colour that is a function": { ...BASE_CONFIG, sankey: { linkColor: "url(x)" } },
			"a sankey alignment": { ...BASE_CONFIG, sankey: { nodeAlignment: "evil" } },
			"a null theme": { ...BASE_CONFIG, theme: null }
		};
		for (const [name, config] of Object.entries(bad)) {
			expect({ name, ok: accepted(flow(config)) }).toEqual({ name, ok: false });
		}
	});

	test("rejects text that is not the plain JSON the builder writes", () => {
		const header = (value: string) => `---\nconfig: ${value}\n---\n${BODY}`;
		const good = JSON.stringify(BASE_CONFIG);
		const bad: Record<string, string> = {
			"a repeated key": "{\"theme\":\"base\",\"theme\":\"dark\"}",
			"an escape sequence": "{\"theme\":\"base\",\"themeVariables\":{\"a\":\"#fff\\u0041\"}}",
			"an escaped quote": "{\"theme\":\"base\",\"themeVariables\":{\"fontFamily\":\"a\\\"b\"}}",
			"a prototype key": "{\"__proto__\":{\"theme\":\"base\"}}",
			"text after the object": `${good} extra`,
			"a second object": `${good}${good}`,
			"an unterminated object": good.slice(0, -1),
			"a missing colon": "{\"theme\" \"base\"}",
			"a trailing comma": "{\"theme\":\"base\",}",
			"a single-quoted string": "{'theme':'base'}",
			"an unquoted key": "{theme:\"base\"}",
			"an array": "[\"base\"]",
			"a number with an exponent": "{\"theme\":\"base\",\"handDrawnSeed\":1e3}",
			"a number with a leading zero": "{\"theme\":\"base\",\"handDrawnSeed\":007}",
			"a null": "{\"theme\":null}",
			"a bare scalar": "base",
			"objects nested too deep": "{\"themeVariables\":{\"xyChart\":{\"a\":{\"b\":{\"c\":\"#fff\"}}}}}"
		};
		for (const [name, value] of Object.entries(bad)) {
			expect({ name, ok: accepted(header(value)) }).toEqual({ name, ok: false });
		}
	});

	test("rejects a flow object that is followed by indented lines, a second config, or an oversized header", () => {
		const good = JSON.stringify(BASE_CONFIG);
		expect(accepted(`---\nconfig: ${good}\n  theme: dark\n---\n${BODY}`)).toBe(false);
		expect(accepted(`---\nconfig: ${good}\nconfig: ${good}\n---\n${BODY}`)).toBe(false);
		expect(accepted(`---\nconfig:\n  theme: base\nconfig: ${good}\n---\n${BODY}`)).toBe(false);
		const wide = { ...BASE_CONFIG, themeVariables: Object.fromEntries(Array.from({ length: 200 }, (_, index) => [`v${index}`, "#fff"])) };
		expect(accepted(flow(wide))).toBe(false);
		const long = { ...BASE_CONFIG, themeVariables: { fontFamily: "a".repeat(9000) } };
		expect(accepted(flow(long))).toBe(false);
	});

	test("reads the indented form against the same schema", () => {
		const block = [
			"---",
			"config:",
			"  theme: base",
			"  look: handDrawn",
			"  handDrawnSeed: 12",
			"  themeVariables:",
			"    primaryColor: \"#352FA0\"",
			"    fontFamily: Menlo, Monaco, monospace",
			"    fontSize: 16px",
			"    pieOpacity: \"1\"",
			"    xyChart:",
			"      backgroundColor: transparent",
			"      plotColorPalette: \"#111111,#222222\"",
			"  flowchart:",
			"    curve: basis",
			"    padding: 14",
			"---",
			BODY
		].join("\n");
		expect(accepted(block)).toBe(true);
		const bad: Record<string, string> = {
			"fontFamily at the top": block.replace("  look: handDrawn", "  fontFamily: x"),
			"a key outside the schema": block.replace("  look: handDrawn", "  themeCSS: x"),
			"a repeated key": block.replace("  look: handDrawn", "  theme: dark"),
			"a bare colour (a YAML comment)": block.replace("\"#352FA0\"", "#352FA0"),
			"a colour name": block.replace("\"#352FA0\"", "red"),
			"inconsistent indentation": block.replace("    fontSize: 16px", "      fontSize: 16px"),
			"a tab": block.replace("    fontSize: 16px", "\tfontSize: 16px"),
			"an escape": block.replace("\"#352FA0\"", "\"#35\\u0041\""),
			"a declaration in fontFamily": block.replace("Menlo, Monaco, monospace", "x; y"),
			"an unknown top-level key": block.replace("---\nconfig:", "---\nsecurity: loose\nconfig:")
		};
		for (const [name, source] of Object.entries(bad)) {
			expect({ name, ok: accepted(source) }).toEqual({ name, ok: false });
		}
	});
});
